/**
 * Elastic deformation of a beam-shaped visual (a box or a cylinder) by modal coordinates (assumed modes, Euler-Bernoulli), or by the twist of a lumped torsion spring (basis linear). The beam frame has its origin at end A (s = 0) and its x axis along the beam to end B (s = L). "bending-y" deflects along the beam y axis (sections rotate about z by the slope), "bending-z" along the beam z axis (sections rotate about y), "torsion" rotates the sections about x. Deflection w(s) = sum_n phi_n(s) * eta_n (eta in m), twist theta(s) = sum_n psi_n(s) * eta_n (eta in rad), with the mode shapes of `basis` normalised to (1/L) * integral_0^L phi_n^2 ds = 1. Deformation bindings of one visual (at most one per family) compose and must give the same `beam`. The rigid motion of the beam frame is the pose binding of the link the visual belongs to.
 */
export interface DeformationBinding {
  target: string;
  property: "deformation";
  family: DeformationFamily;
  basis: DeformationBasis;
  beam: BeamMapping;
  /**
   * The modal coordinates eta_1..eta_n of the family, one signal per mode in mode order (1 to 3 modes). Bending coordinates are in m, torsion coordinates in rad. A FlexibleBeam block records them as <Block>/eta_y[i], <Block>/eta_z[i] and <Block>/eta_t[i].
   *
   * @minItems 1
   * @maxItems 3
   */
  signal: [BindingSignal] | [BindingSignal, BindingSignal] | [BindingSignal, BindingSignal, BindingSignal];
  /**
   * Multiplies every modal coordinate (default 1), e.g. 0.001 for coordinates in mm. The viewer's exaggeration factor is a display setting and is not stored in the binding.
   */
  gain?: number;
  strain?: StrainColor;
  $comment?: string;
}
/**
 * Where the beam frame sits in the visual. `axis` is the visual-local direction from end A to end B; end A is the face of the shape on the other side (boxes and cylinders are centred on their origin, so end A is at -extent/2 along `axis`). `y` is the visual-local direction of the beam y axis, perpendicular to `axis` (default: +y, or +z when `axis` is along y); the beam z axis is axis x y. A cylinder's own axis is its local z, so a cylinder takes `axis` +z or -z.
 */
export interface BeamMapping {
  axis: ShapeAxis;
  y?: ShapeAxis;
  /**
   * Beam length L in m: the mode shapes run over s = 0..L from end A. Default: the extent of the shape along `axis`. Parts of the shape beyond L move rigidly with the section at L.
   */
  length?: number;
  /**
   * Where the neutral axis of the bending lies, as [y, z] in m along the beam y and z axes from the centre line of the shape (default [0, 0]: the shape bends about its own centre line). For a shape that is one part of a built-up section, such as a flange of an I-beam drawn as its own box: the sections of the shape then turn about the neutral axis of the whole section, and the outer fibre of its strain colouring is the point of the shape farthest from that axis (|y| + half the size along beam y, and the same along z).
   *
   * @minItems 2
   * @maxItems 2
   */
  neutral?: [number, number];
  $comment?: string;
}
/**
 * Colours the visual by the bending strain magnitude along the beam, c * |w''(s)|, with c the distance of the outer fibre from the neutral axis (half the box size across the beam, or the cylinder radius, plus the offset of the beam mapping's `neutral` axis), over the bending families of the visual. Uses the true deformation, never the exaggerated one. `range` is in strain (dimensionless, e.g. [0, 0.001]).
 */
export interface StrainColor {
  colormap: Colormap;
  /**
   * @minItems 2
   * @maxItems 2
   */
  range: [number, number];
}
/**
 * Elastic deformation of a mesh visual (a GLB) by modal coordinates: a flexible body reduced from a finite element mesh (ModalBody3D). The GLB's single mesh carries one glTF morph target per elastic mode, in mode order, and the POSITION delta of target k is the shape of mode k per unit modal coordinate (m per unit eta_k) in the visual's frame. The viewer draws vertex = rest + sum_k (gain * eta_k * exaggeration) * delta_k, where the exaggeration is the viewer's display factor (not stored). Only a mesh visual takes it, at most one per visual, and its mesh needs at least as many morph targets as the binding has signals. The rigid motion of the body frame is the pose binding of the link the visual belongs to. The optional `stress` colours the mesh by the von Mises stress the same modal coordinates cause (the GLB's stress table).
 */
export interface ModeShapeBinding {
  target: string;
  property: "mode-shapes";
  /**
   * The modal coordinates eta_1..eta_n in m, one signal per mode in morph-target order (1 to 64 modes). A ModalBody3D block records them as <Block>/eta[i].
   *
   * @minItems 1
   * @maxItems 64
   */
  signal: [BindingSignal, ...BindingSignal[]];
  /**
   * Multiplies every modal coordinate (default 1), e.g. 0.001 for coordinates in mm. The viewer's exaggeration factor is a display setting and is not stored in the binding.
   */
  gain?: number;
  stress?: StressColor;
  $comment?: string;
}
/**
 * Colours a mode-shapes mesh by the per-vertex von Mises stress, recovered from the stress table of its GLB (written by the FEM reduction julia/BGSimFEM as asset.extras.bgsim.stress: the six stress components per vertex per unit modal coordinate). The viewer superposes the table with the binding's modal coordinates (gain applied), sigma(v) = sum_k eta_k S_k(v), and takes von Mises; it uses the true coordinates, never the exaggerated deformation. `range` is in Pa (e.g. [0, 5e7]).
 */
export interface StressColor {
  colormap: Colormap;
  /**
   * von Mises stress at the low and the high end of the colormap, in Pa.
   *
   * @minItems 2
   * @maxItems 2
   */
  range: [number, number];
}
/**
 * A bar between two moving points, such as a truss member between two pin nodes. Each frame the viewer places the visual (a box or a cylinder) so that its `axis` runs from end point A to end point B: the visual is centred between the points, turned onto the line A-B and stretched along `axis` to the distance |AB| (its cross-section keeps its size). The binding replaces the visual's pose in its link. `axis` is the visual-local direction that runs from A to B (default +z for a cylinder, its own axis, and +x for a box). `broken` is an optional failure flag of the bar (for example a Truss2D `failed[k]` or a Bar2D `broken`): above 0.5 the bar is drawn as `brokenStyle`. Colour the bar with a `color` binding of the same visual (for example a utilisation signal on the coolwarm colormap) and hide it with a `visible` binding.
 */
export interface SegmentBinding {
  target: string;
  property: "segment";
  /**
   * The end points, A then B, in metres in the world frame: 4 signals (uA, vA, uB, vB) for a planar model, mapped into the world by `plane` and `depth`, or 6 signals (xA, yA, zA, xB, yB, zB). The count is checked by the viewer (E304: 4 or 6).
   *
   * @minItems 4
   * @maxItems 6
   */
  signal:
    | [BindingSignal, BindingSignal, BindingSignal, BindingSignal]
    | [BindingSignal, BindingSignal, BindingSignal, BindingSignal, BindingSignal]
    | [BindingSignal, BindingSignal, BindingSignal, BindingSignal, BindingSignal, BindingSignal];
  plane?: SegmentPlane;
  /**
   * Planar end points only: the world coordinate along the third axis (y for the xz plane), in m. Default 0.
   */
  depth?: number;
  axis?: ShapeAxis;
  broken?: BindingSignal;
  brokenStyle?: SegmentBrokenStyle;
  /**
   * Multiplies every end point coordinate (default 1), for example 0.001 for coordinates in mm.
   */
  gain?: number;
  /**
   * Added to every end point coordinate after the gain (default 0).
   */
  offset?: number;
  $comment?: string;
}
